from PIL import Image
import numpy as np, math, heapq
im=np.asarray(Image.open('/app/target.png').convert('L'))
mask=im<80
# use crop bbox
mask=mask[420:570,330:700]
# zhang suen
s=mask.copy(); changed=True
while changed:
 changed=False
 for phase in (0,1):
  p=np.pad(s,1)
  P2=p[:-2,1:-1];P3=p[:-2,2:];P4=p[1:-1,2:];P5=p[2:,2:];P6=p[2:,1:-1];P7=p[2:,:-2];P8=p[1:-1,:-2];P9=p[:-2,:-2]
  B=P2.astype(int)+P3+P4+P5+P6+P7+P8+P9
  ring=[P2,P3,P4,P5,P6,P7,P8,P9,P2]
  A=sum(((ring[i]==0)&(ring[i+1]==1)).astype(int) for i in range(8))
  cond=((P2*P4*P6==0)&(P4*P6*P8==0)) if phase==0 else ((P2*P4*P8==0)&(P2*P6*P8==0))
  rem=s&(B>=2)&(B<=6)&(A==1)&cond
  if rem.any(): s[rem]=0; changed=True
# collect 8con comp skeleton
pts=set(zip(*np.where(s)))
comps=[]
while pts:
 root=min(pts); pts.remove(root); comp=[root]; stack=[root]
 while stack:
  y,x=stack.pop()
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if (dy or dx) and (y+dy,x+dx) in pts:
     pts.remove((y+dy,x+dx));stack.append((y+dy,x+dx));comp.append((y+dy,x+dx))
 comps.append(comp)
def build(comp):
 S=set(comp); adj={p:[] for p in S}
 for y,x in S:
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if not(dy or dx):continue
    q=(y+dy,x+dx)
    if q not in S or (y,x)>=q:continue
    if dy and dx and ((y,x+dx) in S or (y+dy,x) in S):continue
    w=math.hypot(dy,dx)
    adj[(y,x)].append((q,w));adj[q].append(((y,x),w))
 # dijkstra all odd nodes paths
 odd=[p for p in S if len(adj[p])%2]
 def shortest(src,dst):
  dist={src:0};prev={};pq=[(0,src)]
  while pq:
   d,u=heapq.heappop(pq)
   if u==dst:break
   if d!=dist[u]:continue
   for v,w in adj[u]:
    nd=d+w
    if nd<dist.get(v,1e9):dist[v]=nd;prev[v]=u;heapq.heappush(pq,(nd,v))
  path=[dst]
  while path[-1]!=src:path.append(prev[path[-1]])
  path.reverse();return dist[dst],path
 dpaths={}
 for i,a in enumerate(odd):
  for b in odd[i+1:]: dpaths[a,b]=shortest(a,b)
 def pairings(items):
  if not items:yield (0,[]);return
  a=items[0]
  for i in range(1,len(items)):
   b=items[i];rest=items[1:i]+items[i+1:]
   for cost,pr in pairings(rest):yield (dpaths[tuple(sorted((a,b)))][0]+cost,[(a,b)]+pr)
 best=(1e9,None,None)
 if len(odd)>=2:
  for i in range(len(odd)):
   for j in range(i+1,len(odd)):
    ends=(odd[i],odd[j]);left=odd[:i]+odd[i+1:j]+odd[j+1:]
    for cost,pairs in pairings(left):
     if cost<best[0]:best=(cost,ends,pairs)
  dupcost,ends,pairs=best
 else: dupcost,ends,pairs=0,(next(iter(S)),)*2,[]
 # edge multiset
 edge_count={}
 def key(a,b):return tuple(sorted((a,b)))
 for a in S:
  for b,w in adj[a]:
   if a<b:edge_count[key(a,b)]=1
 for a,b in pairs:
  _,path=dpaths[tuple(sorted((a,b)))]
  if path[0]!=a:path=path[::-1]
  for u,v in zip(path,path[1:]):edge_count[key(u,v)]=edge_count.get(key(u,v),0)+1
 # adjacency edge ids
 ma={p:[] for p in S};eid=0
 for (a,b),cnt in edge_count.items():
  for _ in range(cnt):ma[a].append((b,eid));ma[b].append((a,eid));eid+=1
 used=set();stack=[ends[0]];route=[]
 while stack:
  u=stack[-1]
  while ma[u] and ma[u][-1][1] in used:ma[u].pop()
  if ma[u]:
   v,e=ma[u].pop();used.add(e);stack.append(v)
  else:route.append(stack.pop())
 route=route[::-1]
 # compress points collinear same direction
 out=[]
 for p in route:
  out.append(p)
  while len(out)>=3:
   a,b,c=out[-3:];v1=(b[0]-a[0],b[1]-a[1]);v2=(c[0]-b[0],c[1]-b[1])
   if v1[0]*v2[1]==v1[1]*v2[0] and v1[0]*v2[0]+v1[1]*v2[1]>0:out.pop(-2)
   else:break
 mm=sum(math.hypot(b[0]-a[0],b[1]-a[1]) for a,b in zip(route,route[1:]))*.22186
 mm2=sum(math.hypot(b[0]-a[0],b[1]-a[1]) for a,b in zip(out,out[1:]))*.22186
 bbox=(min(y for y,x in comp)+420,max(y for y,x in comp)+420,min(x for y,x in comp)+330,max(x for y,x in comp)+330)
 return bbox,len(S),len(odd),dupcost*.22186,mm,mm2,len(route),len(out),out
for c in sorted(comps,key=lambda c:min(x for y,x in c)):
 bbox,n,odd,extra,mm,mm2,nr,no,route=build(c)
 print('bbox',bbox,'nodes',n,'odd',odd,'extra',round(extra,1),'route_mm',round(mm,1),'compressed_mm',round(mm2,1),'pts',nr,'->',no,'start/end',route[0],route[-1])
